The successful open-loop sequence is [2]*8 then [1]: briefly drive right to mount the ramp, then drive left over it. Unit 3 of a4 is high for the first ~8 steps then drops — a good "phase" signal. Let me test a few head designs.

```python
import numpy as np
W0 = W_copy()

def make_head(col_units, biases):
    lines = []
    for j in range(128):
        for c in range(3):
            lines.append(f"actor_head.W[{j}, {c}] = 0")
    for c in range(3):
        lines.append(f"actor_head.b[{c}] = {biases[c]}")
    for c, units in col_units.items():
        for j, v in units.items():
            lines.append(f"actor_head.W[{j}, {c}] = {v}")
    return "\n".join(lines)

# Design 1: unit 3 alone
d1 = make_head({2: {3: 10.0}, 1: {3: -10.0}}, [-5, 0, 0])
W1, _ = apply_edits(d1, params=W0)

# Design 2: phase = mean(early) - mean(late)
early = [3,13,53,54,92,90,121,94,59]
late  = [107,55,8,11,88,21]
cu2 = {2: {}, 1: {}}
for j in early:
    cu2[2][j] = 10.0/len(early); cu2[1][j] = -10.0/len(early)
for j in late:
    cu2[2][j] = -10.0/len(late); cu2[1][j] = 10.0/len(late)
W2, _ = apply_edits(make_head(cu2, [-5,0,0]), params=W0)

# Design 3: body-x unit 41
d3 = make_head({1: {41: 10.0}, 2: {41: -10.0}}, [-5, 0, 0])
W3, _ = apply_edits(d3, params=W0)

for name, Wt in [("unit3", W1), ("phase", W2), ("unit41", W3)]:
    r = simulate(Wt, n=256)
    print(name, "succ", round(r['success'],3), "red", round(r['red'],3),
          "to", round(r['timeout'],3), "ret", round(r['return'],2))
