import numpy as np
W0 = W_copy()
early = [3,13,53,54,92,90,121,94,59]
late  = [107,55,8,11,88,21]

def build(scale, b0=-5):
    lines = []
    for j in range(128):
        for c in range(3):
            lines.append(f"actor_head.W[{j}, {c}] = 0")
    lines += [f"actor_head.b[0] = {b0}", "actor_head.b[1] = 0", "actor_head.b[2] = 0"]
    for j in early:
        lines.append(f"actor_head.W[{j}, 2] = {scale/len(early)}")
        lines.append(f"actor_head.W[{j}, 1] = {-scale/len(early)}")
    for j in late:
        lines.append(f"actor_head.W[{j}, 2] = {-scale/len(late)}")
        lines.append(f"actor_head.W[{j}, 1] = {scale/len(late)}")
    return apply_edits("\n".join(lines), params=W0)[0]

for sc in [10, 20, 40]:
    Wt = build(sc)
    for trial in range(2):
        r = simulate(Wt, n=256)
        print("scale", sc, "trial", trial, "succ", r['success'], "red", r['red'], "to", r['timeout'])
